shell_commands:
cat > /tmp/patch.py <<'EOF'
p='src/orchestration/orchestratorHelpers.test.ts'
s=open(p).read()
s=s.replace("import type {ToolCall} from '../types/ai.js';","import type {ToolCall, TurnUsage} from '../types/ai.js';")
s+='''
// Validates specs/hal-engine-config-hooks/spec.md#3: the hook's usage type names the turn-wide sum.
describe('TurnUsage', () => {
  it('is the type sumUsage returns, so the hook argument reads as a turn total', () => {
    const total: TurnUsage | undefined = sumUsage(undefined, {inputTokens: 1, outputTokens: 2, totalTokens: 3});
    expect(total).toEqual({inputTokens: 1, outputTokens: 2, totalTokens: 3});
  });
});
'''
open(p,'w').write(s)
EOF
python3 /tmp/patch.py; timeout 300 npx jest src/orchestration/orchestratorHelpers.test.ts 2>&1 | tail -20
